const body=$json.body??$json;
const headers=$json.headers??{};
const token=headers['x-filtra-report-token']??headers['X-Filtra-Report-Token']??headers['X-Filtra-Secret']??'';
const expected=String($env.N8N_WEBHOOK_SECRET||$env.N8N_INBOUND_SECRET||$env.N8N_WHATSAPP_REPORT_TOKEN||'').trim();
if(!expected||token!==expected)return[{json:{ok:false,status:401,error:'Unauthorized'}}];
if(!body?.cliente_id||!body?.periodo||!Array.isArray(body.destinatarios))return[{json:{ok:false,status:400,error:'Invalid payload'}}];
if(body.destinatarios.length===0)return[{json:{ok:false,status:400,error:'No recipients'}}];
const report=body.relatorio??body.report??body.message??'';
let message;
if(typeof report==='string')message=report;
else if(report&&typeof report==='object'){message=Object.entries(report).filter(([_,v])=>v!==null&&v!==undefined&&typeof v!=='object').map(([k,v])=>`${k}: ${v}`).join('\n');if(!message.trim())message=JSON.stringify(report);}
else message=String(report??'');
return[{json:{ok:true,cliente_id:String(body.cliente_id),periodo:String(body.periodo),idempotency_key:String(body.idempotency_key||`relatorio:${body.cliente_id}:${body.periodo}`),message,destinatarios:body.destinatarios}}];

const original=$('Separar destinatários').item.json;
const response=$json||{};
const ok=response.ok===true;
return[{json:{...original,delivery_ok:ok,provider_response:response}}];

const items=$input.all();
const results=items.map(item=>{const d=item.json||{};const provider=d.provider_response||{};const ok=d.delivery_ok===true||provider.ok===true;return{channel:d.channel??null,destination:d.destination??null,status:ok?'sent':'failed',ok,error:ok?null:(provider.description||provider.error?.message||provider.error||null),provider_response:provider};});
const failed=results.filter(r=>!r.ok).length;
return[{json:{ok:results.length>0&&failed===0,status:results.length===0?'no_recipients':failed===0?'completed':'partial_failure',total:results.length,sent:results.filter(r=>r.ok).length,failed,results}}];
